    document.body.appendChild(toastContainer);

    function showToast(text, duration = 3000) {
        toastContainer.querySelector('.offline-toast-text').innerText = text;
        toastContainer.classList.add('show');
        setTimeout(() => toastContainer.classList.remove('show'), duration);
    }

    // 3. Chat Trigger Button
    const chatTrigger = document.createElement('div');
    chatTrigger.id = 'offline-chat-trigger';
